import sys
sys.setrecursionlimit(300000)

def main():
    input = sys.stdin.read
    data = input().split()
    idx = 0

    n = int(data[idx]); idx += 1
    c = [0] * (n + 1)
    for i in range(1, n + 1):
        c[i] = int(data[idx]); idx += 1

    adj = [[] for _ in range(n + 1)]
    for _ in range(n - 1):
        u = int(data[idx]); idx += 1
        v = int(data[idx]); idx += 1
        adj[u].append(v)
        adj[v].append(u)

    parent = [0] * (n + 1)
    children = [[] for _ in range(n + 1)]
    order = []
    stack = [1]
    visited = [False] * (n + 1)
    visited[1] = True

    while stack:
        u = stack.pop()
        order.append(u)
        for v in adj[u]:
            if not visited[v]:
                visited[v] = True
                parent[v] = u
                children[u].append(v)
                stack.append(v)

    is_leaf = [False] * (n + 1)
    for i in range(2, n + 1):
        if len(children[i]) == 0:
            is_leaf[i] = True

    dp = [0] * (n + 1)
    count = [0] * (n + 1)

    for u in reversed(order):
        if is_leaf[u]:
            dp[u] = 0
            count[u] = 0
        else:
            total_cost = 0
            total_count = 0
            min_dp = float('inf')
            min_count = 0

            for v in children[u]:
                if dp[v] < min_dp:
                    min_dp = dp[v]
                    min_count = count[v]
                elif dp[v] == min_dp:
                    min_count += count[v]

            if not children[u]:
                continue

            current_min = min_dp
            current_cnt = min_count

            for v in children[u]:
                if dp[v] > current_min:
                    total_cost += dp[v] - current_min
                else:
                    total_cost += 0

            dp[u] = total_cost + c[u]
            count[u] = current_cnt

            if dp[u] > total_cost:
                count[u] = 1
            elif dp[u] == total_cost:
                count[u] += 1

    min_total_cost = dp[1]

    result_vertices = []

    def collect_nodes(u, budget):
        if budget < 0:
            return
        if is_leaf[u]:
            if budget >= 0:
                result_vertices.append(u)
            return

        total_cost_children = 0
        min_child_dp = float('inf')
        for v in children[u]:
            if dp[v] < min_child_dp:
                min_child_dp = dp[v]
            total_cost_children += dp[v] - min_child_dp

        if not children[u]:
            return

        cost_if_not_buy = total_cost_children
        cost_if_buy = dp[u] - c[u]

        if cost_if_buy <= budget:
            result_vertices.append(u)
            for v in children[u]:
                collect_nodes(v, budget - cost_if_buy)
        else:
            for v in children[u]:
                needed = dp[v] - min_child_dp
                collect_nodes(v, budget - needed)

    collect_nodes(1, min_total_cost)

    unique_nodes = sorted(list(set(result_vertices)))

    print(f"{min_total_cost} {len(unique_nodes)}")
    print(" ".join(map(str, unique_nodes)))

if __name__ == "__main__":
    main()
